/// <summary>
/// AVA/WEN/2025/05/21      AVA_013218_ProdSetupRelease
/// </summary>
internal final class AVACreateQOrderResultController  extends SysOperationServiceController
{
}

Method.Source:
protected void new()
{
    super(classStr(AVACreateQOrderResultService), methodStr(AVACreateQOrderResultService, process), SysOperationExecutionMode::Synchronous);
}

public static AVACreateQOrderResultController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVACreateQOrderResultController controller;
    controller = new AVACreateQOrderResultController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

public static void main(Args _args)
{
    AVACreateQOrderResultController controller;
    AVACreateQOrderResultContract contract;
    InventQualityOrderTable inventQOrder;

    controller = AVACreateQOrderResultController::construct();
    if (_args.record() && _args.dataset() == tableNum(InventQualityOrderTable))
    {
        inventQOrder = _args.record();
        if (inventQOrder.ReferenceType == InventTestReferenceType::Production || inventQOrder.ReferenceType == InventTestReferenceType::RouteOpr)
        {
            contract = controller.getDataContractObject();
            contract.parmQOrderId(inventqOrder.QualityOrderId);
        }
    }
    else
    {
        throw Error(Error::missingRecord(tableStr(InventQualityOrderTable)));
    }

    controller.parmArgs(_args);
    controller.startOperation();
}

public boolean parmShowDialog(boolean _showDialog = showDialog)
{    
    return false;
}
